// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker att;

    function setUp() public {
        c = new C();
        att = new Attacker(c);
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        bound(amount, 1, 1e30);

        // fund the adversarial (re-entrant) caller and deposit into c
        vm.deal(address(att), amount);
        att.deposit{value: amount}();

        // drive c through withdrawBalance from the attacker; the attacker's
        // receive() re-enters c.withdrawBalance and reverts if that re-entry SUCCEEDS.
        vm.prank(address(att));
        bool ok;
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for any funded caller, withdrawBalance succeeds.
        // Correct C: re-entry is blocked by the lock, inner call fails silently,
        // receive() does not revert, outer call succeeds.
        // Mutant M: re-entry succeeds, receive() reverts, outer call reverts.
        assertTrue(ok);
    }
}

contract Attacker {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function deposit() external payable {
        c.addToBalance{value: msg.value}();
    }

    receive() external payable {
        // re-enter; if the re-entrant withdrawal SUCCEEDS (buggy version), revert
        // so the pending outer send fails and the outer withdrawal reverts.
        (bool s, ) = address(c).call(abi.encodeWithSelector(C.withdrawBalance.selector));
        if (s) revert();
    }
}

