pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 wei, 1e30 wei);
        Attacker a = new Attacker(c);
        vm.deal(address(a), amount);
        a.deposit(amount);
        a.attack();
        // Rule: after the re-entrancy attempt, the attacker's balance in c is zero
        // (the mutex blocks any re-entrant withdrawal from crediting funds again).
        assertTrue(c.getBalance(address(a)) == 0, "reentrant withdraw must not leave a balance");
    }
}

contract Attacker {
    C c;
    bool acted;
    constructor(C _c) { c = _c; }
    function deposit(uint256 amt) external payable {
        c.addToBalance{value: amt}();
    }
    function attack() external {
        c.withdrawBalance();
    }
    receive() external payable {
        if (!acted) {
            acted = true;
            try c.withdrawBalance() {
                c.addToBalance{value: msg.value}();
            } catch {}
        }
    }
}

